// openTestdata opens a file of the testdata directory (generated by
// testdata/attr_gen.c or testdata/bt2_gen.c).
func openTestdata(t *testing.T, name string, opts ...Option) *File {
	t.Helper()
	f, err := Open(filepath.Join("testdata", name), opts...)
	require.NoError(t, err)
	t.Cleanup(func() { f.Close() })
	return f
}

// ohAt loads the object header of the object at path (hard links through
// symbol tables / link messages from the root group).
func ohAt(t *testing.T, f *File, path string) *h5o {
	t.Helper()
	oh, err := f.oProtect(lookupPath(t, f, path))
	require.NoError(t, err)
	return oh
}

// genAttrNames is the attribute naming scheme of testdata/attr_gen.c:
// the attribute created at step i is "attr_KK", KK = (i*7) % n.
func genAttrNames(n int) (byName, byCorder []string) {
	for i := 0; i < n; i++ {
		byName = append(byName, fmt.Sprintf("attr_%02d", i))
		byCorder = append(byCorder, fmt.Sprintf("attr_%02d", (i*7)%n))
	}
	return byName, byCorder
}

// iterNames iterates over the attributes of oh with the given index and
// order and returns the names and creation indexes seen.
func iterNames(t *testing.T, f *File, oh *h5o, idx h5aIndex, order h5aIterOrder) ([]string, []uint32) {
	t.Helper()
	var names []string
	var crt []uint32
	err := f.oAttrIterateReal(oh, idx, order, 0, nil, func(attr *h5oAttr) error {
		names = append(names, attr.name)
		crt = append(crt, attr.crtIdx)
		return nil
	})
	require.NoError(t, err)
	return names, crt
}

// checkGenAttr checks the value of an attribute "attr_KK" of attr_gen.c.
func checkGenAttr(t *testing.T, f *File, attr *h5oAttr) {
	t.Helper()
	var k int
	_, err := fmt.Sscanf(attr.name, "attr_%02d", &k)
	require.NoError(t, err, attr.name)
	vals, err := f.aRead(attr)
	require.NoError(t, err)
	assert.Equal(t, []any{int32(1000 + k)}, vals, attr.name)
	assert.Equal(t, h5.SpaceScalar, attr.ds.typ)
}

func TestAttributeDenseGenerated(t *testing.T) {
	f := openTestdata(t, "attr_dense.h5")

	for _, tc := range []struct {
		path             string
		n                int
		dense            bool
		tracked, indexed bool
	}{
		{"/tracked", 30, true, true, false},
		{"/indexed", 30, true, true, true},
		{"/untracked", 20, true, false, false},
		{"/compact", 5, false, true, false},
		{"/compact_untracked", 5, false, false, false},
	} {
		t.Run(tc.path, func(t *testing.T) {
			oh := ohAt(t, f, tc.path)
			byName, byCorder := genAttrNames(tc.n)

			ainfo, err := f.h5aGetAinfo(oh)
			require.NoError(t, err)
			require.NotNil(t, ainfo)
			assert.Equal(t, tc.dense, addrDefined(ainfo.fheapAddr))
			assert.Equal(t, tc.indexed, addrDefined(ainfo.corderBt2Addr))
			assert.Equal(t, tc.tracked, ainfo.trackCorder)

			n, err := f.aCount(oh)
			require.NoError(t, err)
			assert.Equal(t, uint64(tc.n), n)

			// Name order (strcmp increasing), through aIterate.
			attrs, err := objectAttrs(f, oh)
			require.NoError(t, err)
			var names []string
			for _, a := range attrs {
				names = append(names, a.name)
				checkGenAttr(t, f, a)
			}
			assert.Equal(t, byName, names)

			// Decreasing name order.
			names, _ = iterNames(t, f, oh, h5aIndexName, h5aIterDec)
			rev := append([]string(nil), byName...)
			sort.Sort(sort.Reverse(sort.StringSlice(rev)))
			assert.Equal(t, rev, names)

			// Native name order: hash order for dense storage, header
			// order for compact storage.
			names, _ = iterNames(t, f, oh, h5aIndexName, h5aIterNative)
			if !tc.dense {
				assert.Equal(t, byCorder, names)
			}
			sort.Strings(names)
			assert.Equal(t, byName, names)

			// Creation order. libhdf5 does not refuse creation order
			// iteration when the creation order is not tracked: compact
			// attributes get their position in the header as a bogus
			// creation index.
			for _, order := range []h5aIterOrder{h5aIterInc, h5aIterNative} {
				names, crt := iterNames(t, f, oh, h5aIndexCrtOrder, order)
				if tc.tracked || !tc.dense {
					if order == h5aIterInc || tc.indexed || !tc.dense {
						assert.Equal(t, byCorder, names, "order %d", order)
					}
					sorted := append([]uint32(nil), crt...)
					sort.Slice(sorted, func(i, j int) bool { return sorted[i] < sorted[j] })
					for i, c := range sorted {
						assert.Equal(t, uint32(i), c)
					}
				}
				assert.Len(t, names, tc.n)
			}
			names, _ = iterNames(t, f, oh, h5aIndexCrtOrder, h5aIterDec)
			if tc.tracked || !tc.dense {
				rev := append([]string(nil), byCorder...)
				for i, j := 0, len(rev)-1; i < j; i, j = i+1, j-1 {
					rev[i], rev[j] = rev[j], rev[i]
				}
				assert.Equal(t, rev, names)
			}

			// Creation order info.
			for _, a := range attrs {
				info := h5aGetInfo(a)
				if tc.tracked {
					assert.True(t, info.corderValid, a.name)
					assert.Equal(t, byCorder[info.corder], a.name)
				}
				assert.Equal(t, uint64(4), info.dataSize)
			}

			// Open by name: first, last, middle; missing names.
			for _, name := range []string{byName[0], byName[tc.n-1], byName[tc.n/2], byCorder[1]} {
				a, err := f.aOpenByName(oh, name)
				require.NoError(t, err, name)
				assert.Equal(t, name, a.name)
				checkGenAttr(t, f, a)
				if tc.tracked {
					assert.Equal(t, byCorder[a.crtIdx], name)
				}
				ok, err := f.oAttrExists(oh, name)
				require.NoError(t, err)
				assert.True(t, ok)
			}
			for _, name := range []string{"", "attr_", "attr_99", "Attr_00", "attr_00\x00"} {
				_, err := f.aOpenByName(oh, name)
				assert.ErrorIs(t, err, ErrNotFound, "%q", name)
				ok, err := f.oAttrExists(oh, name)
				require.NoError(t, err)
				assert.False(t, ok, "%q", name)
			}

			// Open by index and iteration with skip.
			for _, i := range []int{0, tc.n / 3, tc.n - 1} {
				a, err := f.oAttrOpenByIdx(oh, h5aIndexName, h5aIterInc, uint64(i))
				require.NoError(t, err)
				assert.Equal(t, byName[i], a.name)
				a, err = f.oAttrOpenByIdx(oh, h5aIndexCrtOrder, h5aIterInc, uint64(i))
				require.NoError(t, err)
				if tc.tracked || !tc.dense {
					assert.Equal(t, byCorder[i], a.name)
				}
			}
			_, err = f.oAttrOpenByIdx(oh, h5aIndexName, h5aIterInc, uint64(tc.n))
			assert.Error(t, err)
			var skipped []string
			var last uint64
			err = f.oAttrIterateReal(oh, h5aIndexName, h5aIterInc, 3, &last, func(attr *h5oAttr) error {
				skipped = append(skipped, attr.name)
				return nil
			})
			require.NoError(t, err)
			assert.Equal(t, byName[3:], skipped)
			assert.Equal(t, uint64(tc.n), last)

			// Early stop.
			var seen int
			err = f.aIterate(oh, func(attr *h5oAttr) error {
				seen++
				if seen == 2 {
					return errBIterStop
				}
				return nil
			})
			require.NoError(t, err)
			assert.Equal(t, 2, seen)
			stopErr := fmt.Errorf("callback failed")
			err = f.aIterate(oh, func(attr *h5oAttr) error { return stopErr })
			assert.ErrorIs(t, err, stopErr)
		})
	}
}

// TestAttributeDenseBt2Corder reads the dense attributes of
// testdata/bt2_corder.h5 ("/filtered": "attr00".."attr49", int32 scalar
// value i, creation order indexed).
func TestAttributeDenseBt2Corder(t *testing.T) {
	f := openTestdata(t, "bt2_corder.h5")
	oh := ohAt(t, f, "/filtered")
	n, err := f.aCount(oh)
	require.NoError(t, err)
	assert.Equal(t, uint64(50), n)
	attrs, err := objectAttrs(f, oh)
	require.NoError(t, err)
	require.Len(t, attrs, 50)
	for i, a := range attrs {
		assert.Equal(t, fmt.Sprintf("attr%02d", i), a.name)
		assert.Equal(t, uint32(i), a.crtIdx)
		vals, err := f.aRead(a)
		require.NoError(t, err)
		assert.Equal(t, []any{int32(i)}, vals)
	}
	names, _ := iterNames(t, f, oh, h5aIndexCrtOrder, h5aIterNative)
	for i, name := range names {
		assert.Equal(t, fmt.Sprintf("attr%02d", i), name)
	}
}

// TestAttributeDenseCorpus reads the only object of the repository corpus
// with dense attribute storage: the dataset of h5stat_newgrat.h5 (100
// attributes "ATTR1".."ATTR100", reached through the dense link storage of
// the root group).
func TestAttributeDenseCorpus(t *testing.T) {
	f := openTestFile(t, "tools/test/h5stat/testfiles/h5stat_newgrat.h5")
	rootOh, err := f.oProtect(f.sblock.rootAddr)
	require.NoError(t, err)
	v, err := f.msgRead(rootOh, h5oLinfoID)
	require.NoError(t, err)
	addr := haddrUndef
	require.NoError(t, denseLinks(f, v.(*h5oLinfo), func(l *h5oLink) {
		if l.name == "DATASET_NAME" {
			addr = l.addr
		}
	}))
	oh, err := f.oProtect(addr)
	require.NoError(t, err)

	ainfo, err := f.h5aGetAinfo(oh)
	require.NoError(t, err)
	require.True(t, addrDefined(ainfo.fheapAddr))

	n, err := f.aCount(oh)
	require.NoError(t, err)
	assert.Equal(t, uint64(100), n)
	attrs, err := objectAttrs(f, oh)
	require.NoError(t, err)
	var want []string
	for i := 1; i <= 100; i++ {
		want = append(want, fmt.Sprintf("ATTR%d", i))
	}
	sort.Strings(want) // strcmp order: ATTR1, ATTR10, ATTR100, ATTR11, ...
	var got []string
	for _, a := range attrs {
		got = append(got, a.name)
		vals, err := f.aRead(a)
		require.NoError(t, err)
		require.Len(t, vals, 1)
		assert.IsType(t, int32(0), vals[0])
	}
	assert.Equal(t, want, got)
	assert.Equal(t, "ATTR1", got[0])
	assert.Equal(t, "ATTR10", got[1])
	assert.Equal(t, "ATTR100", got[2])
	for _, name := range []string{"ATTR1", "ATTR100", "ATTR99", "ATTR50"} {
		a, err := f.aOpenByName(oh, name)
		require.NoError(t, err)
		assert.Equal(t, name, a.name)
	}
	_, err = f.aOpenByName(oh, "ATTR101")
	assert.ErrorIs(t, err, ErrNotFound)
}

// corruptionVariants calls check on corrupted copies of the file image
// data: every step-th byte inverted (one at a time) and a few truncations.
func corruptionVariants(t *testing.T, data []byte, step int, check func(name string, img []byte)) {
	for off := 0; off < len(data); off += step {
		img := append([]byte(nil), data...)
		img[off] ^= 0xff
		check(fmt.Sprintf("flip@%d", off), img)
	}
	for _, n := range []int{len(data) / 4, len(data) / 2, len(data) * 3 / 4, len(data) - 1} {
		check(fmt.Sprintf("truncate@%d", n), append([]byte(nil), data[:n]...))
	}
}

// exerciseAttributes runs every attribute entry point over every object of
// f, ignoring errors.
func exerciseAttributes(f *File) {
	objs, _ := attrWalk(f, 1000)
	for _, obj := range objs {
		_, _ = f.aCount(obj.oh)
		_ = f.aIterate(obj.oh, func(attr *h5oAttr) error {
			_, _ = f.aRead(attr)
			_, _ = f.aOpenByName(obj.oh, attr.name)
			return nil
		})
		for _, idx := range []h5aIndex{h5aIndexName, h5aIndexCrtOrder} {
			_ = f.oAttrIterateReal(obj.oh, idx, h5aIterNative, 0, nil, func(attr *h5oAttr) error { return nil })
		}
		_, _ = f.aOpenByName(obj.oh, "attr_07")
		_, _ = f.oAttrExists(obj.oh, "attr_13")
		for _, m := range obj.oh.mesgs {
			_, _ = f.h5oLoadNative(obj.oh, m)
		}
	}
	_, _ = f.smGetInfo()
}

func TestAttributeCorruption(t *testing.T) {
	for _, name := range []string{"attr_dense.h5", "attr_sohm.h5"} {
		data, err := os.ReadFile(filepath.Join("testdata", name))
		require.NoError(t, err)
		for _, verify := range []bool{false, true} {
			step := 3
			if verify {
				step = 17
			}
			corruptionVariants(t, data, step, func(variant string, img []byte) {
				defer func() {
					if r := recover(); r != nil {
						t.Errorf("%s %s (checksums %v): panic: %v\n%s", name, variant, verify, r, debug.Stack())
					}
				}()
				f, err := OpenReader(bytes.NewReader(img), int64(len(img)), WithChecksumVerification(verify))
				if err != nil {
					return
				}
				defer f.Close()
				exerciseAttributes(f)
			})
		}
	}
}
